import java.util.Arrays;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] a = new int[6];
        Arrays.fill(a, 0);
        if (n > 0) a[0] = sc.nextInt();
        if (n > 1) a[1] = sc.nextInt();
        if (n > 2) a[2] = sc.nextInt();
        if (n > 3) a[3] = sc.nextInt();
        if (n == 5) a[4] = sc.nextInt();

        // Bubble sort
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n - i - 1; ++j) {
                if (a[j] > a[j + 1]) {
                    int temp = a[j];
                    a[j] = a[j + 1];
                    a[j + 1] = temp;
                }
            }
        }

        int t = (a[0] + a[n - 1]) >> 1;
        int left = -1, right = n;
        while (++left < n && a[left] <= t);
        while (--right >= 0 && a[right] >= t);
        int candidate1 = (left > 0 && Math.abs(a[left - 1] - t) < Math.abs(a[left] - t))
                ? a[left - 1]
                : a[left];
        int candidate2 = (right >= 0 && Math.abs(a[right] - t) < Math.abs(a[right + 1] - t))
                ? a[right]
                : a[right + 1];
        System.out.println(Math.abs(a[left] - t) < Math.abs(a[right] - t) ? candidate1 : candidate2);
        sc.close();
    }
}
